-- v4.4.0 native governed software delivery graph.  All objects are additive.
-- APPROVED_BASELINE records are immutable; EXPECTED_VERSION fences patches.
DECLARE
  PROCEDURE ddl(s VARCHAR2) IS
  BEGIN
    EXECUTE IMMEDIATE s;
  EXCEPTION WHEN OTHERS THEN
    IF INSTR(LOWER(SQLERRM), 'already used') = 0
       AND INSTR(LOWER(SQLERRM), 'already exists') = 0 THEN
      RAISE;
    END IF;
  END;
BEGIN
  ddl('CREATE TABLE "SPEC_VERSIONS" (VERSION_ID VARCHAR(128) PRIMARY KEY,SPEC_ID VARCHAR(128) NOT NULL,VERSION_NUMBER BIGINT NOT NULL,CHANGE_TYPE VARCHAR(64) NOT NULL,CHANGE_SUMMARY VARCHAR(2000),DIFF_JSON CLOB DEFAULT ''{}'' NOT NULL,CREATED_BY VARCHAR(256),CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,CONSTRAINT UK_SPEC_VERSION UNIQUE(SPEC_ID,VERSION_NUMBER))');
  ddl('CREATE TABLE CX_SDD_CHANGES (CHANGE_ID VARCHAR(128) PRIMARY KEY,TITLE VARCHAR(512) NOT NULL,SUMMARY CLOB,PROFILE_KEY VARCHAR(64) NOT NULL,SECURITY_DOMAIN_ID VARCHAR(128),STATUS VARCHAR(32) NOT NULL,CURRENT_REVISION_ID VARCHAR(128),CREATED_BY VARCHAR(256) NOT NULL,UPDATED_BY VARCHAR(256) NOT NULL,CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,UPDATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL)');
  ddl('CREATE TABLE CX_SDD_SOURCE_SNAPSHOTS (SNAPSHOT_ID VARCHAR(128) PRIMARY KEY,CHANGE_ID VARCHAR(128) NOT NULL,SOURCE_FORMAT VARCHAR(32) NOT NULL,CONTENT_JSON CLOB NOT NULL,CONTENT_DIGEST VARCHAR(64) NOT NULL,CREATED_BY VARCHAR(256) NOT NULL,CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,CONSTRAINT UK_SDD_SNAPSHOT_DIGEST UNIQUE(CHANGE_ID,CONTENT_DIGEST))');
  ddl('CREATE TABLE CX_SDD_REVISIONS (REVISION_ID VARCHAR(128) PRIMARY KEY,CHANGE_ID VARCHAR(128) NOT NULL,REVISION_NO BIGINT NOT NULL,REVISION_STATE VARCHAR(32) NOT NULL,SOURCE_KIND VARCHAR(32) NOT NULL,SOURCE_SNAPSHOT_ID VARCHAR(128),CONTENT_DIGEST VARCHAR(64) NOT NULL,EXPECTED_VERSION BIGINT DEFAULT 1 NOT NULL,BASELINE_OF_REVISION_ID VARCHAR(128),APPROVED_BY VARCHAR(256),APPROVED_AT TIMESTAMP,CREATED_BY VARCHAR(256) NOT NULL,CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,REASON VARCHAR(2000),CONSTRAINT UK_SDD_REVISION UNIQUE(CHANGE_ID,REVISION_NO))');
  ddl('CREATE TABLE CX_SDD_CLAUSES (CLAUSE_ID VARCHAR(128) PRIMARY KEY,REVISION_ID VARCHAR(128) NOT NULL,CLAUSE_KIND VARCHAR(64) NOT NULL,CLAUSE_KEY VARCHAR(128) NOT NULL,TITLE VARCHAR(1000) NOT NULL,BODY_TEXT CLOB,STRUCTURED_JSON CLOB DEFAULT ''{}'' NOT NULL,STATUS VARCHAR(32) NOT NULL,ORDINAL BIGINT DEFAULT 0 NOT NULL,EXPECTED_VERSION BIGINT DEFAULT 1 NOT NULL,CREATED_BY VARCHAR(256) NOT NULL,UPDATED_BY VARCHAR(256) NOT NULL,CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,UPDATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,CONSTRAINT UK_SDD_CLAUSE_KEY UNIQUE(REVISION_ID,CLAUSE_KEY))');
  ddl('CREATE TABLE CX_SDD_UNRESOLVED_FRAGMENTS (FRAGMENT_ID VARCHAR(128) PRIMARY KEY,REVISION_ID VARCHAR(128) NOT NULL,FRAGMENT_KIND VARCHAR(64) NOT NULL,SOURCE_PATH VARCHAR(1024),SOURCE_OFFSET BIGINT,CONTENT_DIGEST VARCHAR(64) NOT NULL,SUMMARY CLOB,STATUS VARCHAR(32) NOT NULL,WAIVED_BY VARCHAR(256),WAIVER_REASON VARCHAR(2000),WAIVER_EXPIRES_AT TIMESTAMP,CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL)');
  ddl('CREATE TABLE CX_SDD_TASKS (TASK_ID VARCHAR(128) PRIMARY KEY,REVISION_ID VARCHAR(128) NOT NULL,TITLE VARCHAR(1000) NOT NULL,ROLE_KEY VARCHAR(64) NOT NULL,RISK_LEVEL VARCHAR(16) NOT NULL,READ_SET_JSON CLOB DEFAULT ''[]'' NOT NULL,WRITE_SET_JSON CLOB DEFAULT ''[]'' NOT NULL,DEPENDS_ON_JSON CLOB DEFAULT ''[]'' NOT NULL,STATUS VARCHAR(32) NOT NULL,ASSIGNED_PRINCIPAL_ID VARCHAR(256),EXPECTED_VERSION BIGINT DEFAULT 1 NOT NULL,CREATED_BY VARCHAR(256) NOT NULL,UPDATED_BY VARCHAR(256) NOT NULL,CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,UPDATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL)');
  ddl('CREATE TABLE CX_SDD_RESOURCE_LEASES (LEASE_ID VARCHAR(128) PRIMARY KEY,RUN_ID VARCHAR(128),TASK_ID VARCHAR(128) NOT NULL,RESOURCE_KIND VARCHAR(64) NOT NULL,RESOURCE_REF VARCHAR(2048) NOT NULL,OWNER_PRINCIPAL_ID VARCHAR(256) NOT NULL,FENCING_TOKEN BIGINT DEFAULT 1 NOT NULL,STATUS VARCHAR(32) NOT NULL,LEASE_EXPIRES_AT TIMESTAMP NOT NULL,CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,UPDATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,CONSTRAINT UK_SDD_RESOURCE_LEASE UNIQUE(RESOURCE_KIND,RESOURCE_REF,STATUS))');
  ddl('CREATE TABLE CX_SDD_RUNS (RUN_ID VARCHAR(128) PRIMARY KEY,REVISION_ID VARCHAR(128) NOT NULL,GRAPH_VERSION_ID VARCHAR(128),STATUS VARCHAR(32) NOT NULL,RISK_LEVEL VARCHAR(16) DEFAULT ''LOW'' NOT NULL,BUDGET_JSON CLOB DEFAULT ''{}'' NOT NULL,CONTEXT_DIGEST VARCHAR(64),CREATED_BY VARCHAR(256) NOT NULL,CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,UPDATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL)');
  ddl('CREATE TABLE CX_SDD_RUN_NODES (RUN_NODE_ID VARCHAR(128) PRIMARY KEY,RUN_ID VARCHAR(128) NOT NULL,TASK_ID VARCHAR(128),NODE_KEY VARCHAR(256) NOT NULL,STATUS VARCHAR(32) NOT NULL,READ_SET_JSON CLOB DEFAULT ''[]'' NOT NULL,WRITE_SET_JSON CLOB DEFAULT ''[]'' NOT NULL,CHECKPOINT_DIGEST VARCHAR(64),CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,UPDATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,CONSTRAINT UK_SDD_RUN_NODE UNIQUE(RUN_ID,NODE_KEY))');
  ddl('CREATE TABLE CX_SDD_EVIDENCE (EVIDENCE_ID VARCHAR(128) PRIMARY KEY,REVISION_ID VARCHAR(128) NOT NULL,TASK_ID VARCHAR(128),CRITERION_CLAUSE_ID VARCHAR(128),EVIDENCE_TYPE VARCHAR(64) NOT NULL,SOURCE_KIND VARCHAR(64) NOT NULL,REFERENCE_URI VARCHAR(2048),ARTIFACT_DIGEST VARCHAR(128) NOT NULL,DETAIL_JSON CLOB DEFAULT ''{}'' NOT NULL,INDEPENDENT_FLAG CHAR(1) DEFAULT ''N'' NOT NULL,STATUS VARCHAR(32) NOT NULL,CREATED_BY VARCHAR(256) NOT NULL,CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL)');
  ddl('CREATE TABLE CX_SDD_REVIEWS (REVIEW_ID VARCHAR(128) PRIMARY KEY,REVISION_ID VARCHAR(128) NOT NULL,TASK_ID VARCHAR(128),REVIEW_KIND VARCHAR(64) NOT NULL,STATUS VARCHAR(32) NOT NULL,REVIEWER_PRINCIPAL_ID VARCHAR(256),DECISION_REASON VARCHAR(2000),CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,DECIDED_AT TIMESTAMP)');
  ddl('CREATE TABLE CX_SDD_GATES (GATE_ID VARCHAR(128) PRIMARY KEY,RUN_ID VARCHAR(128) NOT NULL,GATE_KIND VARCHAR(64) NOT NULL,STATUS VARCHAR(32) NOT NULL,RISK_LEVEL VARCHAR(16) NOT NULL,IMPACT_JSON CLOB DEFAULT ''{}'' NOT NULL,DECISION VARCHAR(32),DECISION_REASON VARCHAR(2000),CREATED_BY VARCHAR(256) NOT NULL,DECIDED_BY VARCHAR(256),CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,DECIDED_AT TIMESTAMP)');
  ddl('CREATE TABLE CX_SDD_SCM_CONNECTIONS (CONNECTION_ID VARCHAR(128) PRIMARY KEY,ADAPTER_KIND VARCHAR(32) NOT NULL,REPOSITORY_REF VARCHAR(2048) NOT NULL,CREDENTIAL_REFERENCE VARCHAR(512),POLICY_JSON CLOB DEFAULT ''{}'' NOT NULL,STATUS VARCHAR(32) NOT NULL,CREATED_BY VARCHAR(256) NOT NULL,CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,UPDATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,CONSTRAINT UK_SDD_SCM_REPO UNIQUE(ADAPTER_KIND,REPOSITORY_REF))');
  ddl('CREATE TABLE CX_SDD_ARTIFACTS (ARTIFACT_ID VARCHAR(128) PRIMARY KEY,RUN_ID VARCHAR(128),TASK_ID VARCHAR(128),ARTIFACT_KIND VARCHAR(64) NOT NULL,REFERENCE_URI VARCHAR(2048) NOT NULL,CONTENT_DIGEST VARCHAR(128) NOT NULL,STATUS VARCHAR(32) NOT NULL,CREATED_BY VARCHAR(256) NOT NULL,CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,CONSTRAINT UK_SDD_ARTIFACT_DIGEST UNIQUE(REFERENCE_URI,CONTENT_DIGEST))');
  ddl('CREATE INDEX IDX_SDD_CHANGE_STATUS ON CX_SDD_CHANGES(STATUS,UPDATED_AT)');
  ddl('CREATE INDEX IDX_SDD_REVISION_STATE ON CX_SDD_REVISIONS(CHANGE_ID,REVISION_STATE)');
  ddl('CREATE INDEX IDX_SDD_TASK_STATUS ON CX_SDD_TASKS(REVISION_ID,STATUS)');
  ddl('CREATE INDEX IDX_SDD_EVIDENCE_REV ON CX_SDD_EVIDENCE(REVISION_ID,STATUS)');
END;
/
MERGE INTO CX_PLATFORM_CAPABILITIES d USING (SELECT 'native_sdd_control_plane' CAPABILITY_KEY FROM DUAL) s ON (d.CAPABILITY_KEY=s.CAPABILITY_KEY) WHEN NOT MATCHED THEN INSERT (CAPABILITY_KEY,MANDATORY) VALUES (s.CAPABILITY_KEY,'Y');
MERGE INTO CX_PLATFORM_CAPABILITIES d USING (SELECT 'governed_sdd_execution' CAPABILITY_KEY FROM DUAL) s ON (d.CAPABILITY_KEY=s.CAPABILITY_KEY) WHEN NOT MATCHED THEN INSERT (CAPABILITY_KEY,MANDATORY) VALUES (s.CAPABILITY_KEY,'Y');
MERGE INTO CX_PLATFORM_CAPABILITIES d USING (SELECT 'software_delivery_profile' CAPABILITY_KEY FROM DUAL) s ON (d.CAPABILITY_KEY=s.CAPABILITY_KEY) WHEN NOT MATCHED THEN INSERT (CAPABILITY_KEY,MANDATORY) VALUES (s.CAPABILITY_KEY,'Y');
MERGE INTO CX_PLATFORM_CAPABILITIES d USING (SELECT 'sdd_workbench' CAPABILITY_KEY FROM DUAL) s ON (d.CAPABILITY_KEY=s.CAPABILITY_KEY) WHEN NOT MATCHED THEN INSERT (CAPABILITY_KEY,MANDATORY) VALUES (s.CAPABILITY_KEY,'Y');
MERGE INTO CX_PLATFORM_CAPABILITIES d USING (SELECT 'scm_execution_adapters' CAPABILITY_KEY FROM DUAL) s ON (d.CAPABILITY_KEY=s.CAPABILITY_KEY) WHEN NOT MATCHED THEN INSERT (CAPABILITY_KEY,MANDATORY) VALUES (s.CAPABILITY_KEY,'N');
